def get_connection_to_hana_db():
    """
    Establishes a connection to the HANA database.
    Returns:
        conn: A connection object representing the connection to the HANA database.
    Raises:
        Exception: If there is an error connecting to the HANA database.
    """
    with open(os.path.join(ROOT_PATH_DIR, CONFIG_PATH_DIR, HANADB_CONFIG_FILENAME), 'r') as config_file:  # open .hanadb-config.json from its current folder  
        config_data = json.load(config_file)
    HANA_DB_ADDRESS=config_data["host"]
    HANA_DB_PORT=config_data["port"]
    HANA_DB_USER=config_data["user"]
    HANA_DB_PASSWORD=config_data["password"]
    
    try:
        conn = dbapi.connect(
            address=HANA_DB_ADDRESS,
            port=HANA_DB_PORT,
            user=HANA_DB_USER,
            password=HANA_DB_PASSWORD,
            encrypt=True,
            autocommit=True,
            sslValidateCertificate=False
        )
        return conn
    except Exception as e:
        log.error(f"Error connecting to HANA DB: {str(e)}")

def get_connection_to_hana_string():
    """
    Returns the connection string for connecting to a HANA database.

    The connection string is generated using the variables from the hana config json :
    - address: the address of the HANA database
    - port: the port number of the HANA database
    - user: the username for connecting to the HANA database
    - password: the password for connecting to the HANA database

    Returns:
    str: The connection string for connecting to the HANA database.
    """
    with open(os.path.join(ROOT_PATH_DIR, CONFIG_PATH_DIR, HANADB_CONFIG_FILENAME), 'r') as config_file:  # open .hanadb-config.json from its current folder  
        config_data = json.load(config_file)
    HANA_DB_ADDRESS=config_data["host"]
    HANA_DB_PORT=config_data["port"]
    HANA_DB_USER=config_data["user"]
    HANA_DB_PASSWORD=config_data["password"]

    return "hana+hdbcli://{user}:{password}@{address}:{port}?encrypt=true".format(
        user=HANA_DB_USER,
        password=HANA_DB_PASSWORD,
        address=HANA_DB_ADDRESS,
        port=HANA_DB_PORT,
    )    
